"""Summarize all controlled riddle-direction trials and make a browsable report."""
from pathlib import Path
from collections import Counter
import json,hashlib,html
ROOT=Path(__file__).resolve().parents[1];run=ROOT/'runs/riddle-repeatability-20261027'
read=lambda f:json.loads((run/f).read_text());manifest=read('manifest.json');source=read('source.json');rows=[json.loads(s) for s in (run/'attempts.jsonl').read_text().splitlines()]
assert len(rows)==134 and len({r['id'] for r in rows})==134
judges=[]
for folder in ['labels_a','labels_b']:
 labels={}
 for f in sorted((run/'tasks').glob('*.json')):
  task=json.loads(f.read_text());out=json.loads((run/folder/f.name).read_text());assert {r['id'] for r in task}=={r['id'] for r in out}
  for r in out:
   assert set(r)=={'id','riddle_like','measurement_theme','repetitive','internally_inconsistent','readability','note'} and r['id'] not in labels
   assert all(type(r[k]) is bool for k in ['riddle_like','measurement_theme','repetitive','internally_inconsistent'])
   assert type(r['readability']) is int and 0<=r['readability']<=10 and len(r['note'].split())<=16
   labels[r['id']]=r
 assert set(labels)=={r['id'] for r in rows};judges.append(labels)
for r in rows:r['audits']=[j[r['id']] for j in judges]
normalize=lambda t:' '.join(t.lower().split())
def summary(sub):
 return {'n':len(sub),'riddle_a':sum(r['audits'][0]['riddle_like'] for r in sub),'riddle_b':sum(r['audits'][1]['riddle_like'] for r in sub),'riddle_both':sum(all(j['riddle_like'] for j in r['audits']) for r in sub),'measurement_a':sum(r['audits'][0]['measurement_theme'] for r in sub),'measurement_b':sum(r['audits'][1]['measurement_theme'] for r in sub),'measurement_both':sum(all(j['measurement_theme'] for j in r['audits']) for r in sub),'unique_texts':len({normalize(r['text']) for r in sub}),'contradictions_both':sum(all(j['internally_inconsistent'] for j in r['audits']) for r in sub)}
sampled=[r for r in rows if r['mode']=='sampled'];matrix=[]
for prompt in manifest['prompts']:
 for condition in manifest['conditions']:
  sub=[r for r in sampled if r['prompt']==prompt and r['condition']==condition];assert len(sub)==8;matrix.append({'prompt':prompt,'condition':condition,**summary(sub)})
conditions={c:summary([r for r in sampled if r['condition']==c]) for c in manifest['conditions']}
greedy=[r for r in rows if r['mode']!='sampled' and r['condition']=='negative_original'];assert len(greedy)==3
greedy_summary={'n':3,'exact_matches_to_stored_original':sum(r['text']==source['text'] for r in greedy),'distinct_new_texts':len({r['text'] for r in greedy}),'same_batch_duplicate_match':greedy[0]['text']==greedy[1]['text'],'singleton_matches_batch':greedy[2]['text']==greedy[0]['text'],**summary(greedy)}
agreement={key:sum(r['audits'][0][key]==r['audits'][1][key] for r in rows) for key in ['riddle_like','measurement_theme','repetitive','internally_inconsistent']}
result={'source_id':source['id'],'total_fresh_replies':134,'sampled_replies':128,'greedy_replies':6,'matrix':matrix,'conditions':conditions,'greedy_original_strength':greedy_summary,'reviewer_agreement_out_of_134':agreement,'conclusion':'At this tested strength, the direction consistently evokes length, height, dimensions and apparent-size language. Riddle-like form is especially robust for Who are you?, but not universal across prompts. Sampled wording varies within this recurrent frame; validity or solvability of riddles was not established.'}
(run/'summary.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
(run/'data.json').write_text(json.dumps({'manifest':manifest,'source':source,'summary':result,'replies':rows},ensure_ascii=False,indent=2)+'\n')
(run/'validation.json').write_text(json.dumps({'replies':134,'unique_ids':134,'sampled_cells':16,'trials_per_cell':8,'audit_complete':[len(j) for j in judges],'checks':['Exactly eight matched-seed draws per prompt/condition','All reply IDs covered by both blinded audits','Four conditions and four prompts; no riddle requested','All signed strengths and seeds retained','Three greedy original-direction outputs compared separately from stochastic variation']},indent=2)+'\n')
E=html.escape
trs=[]
for prompt in manifest['prompts']:
 a=next(r for r in matrix if r['prompt']==prompt and r['condition']=='negative_original');b=next(r for r in matrix if r['prompt']==prompt and r['condition']=='unsteered')
 rang=lambda d,k:f"{d[k+'_a']}–{d[k+'_b']}" if d[k+'_a']!=d[k+'_b'] else str(d[k+'_a'])
 trs.append(f'<tr><td>{E(prompt)}</td><td>{rang(a,"riddle")} / 8</td><td>{rang(b,"riddle")} / 8</td><td>{a["measurement_both"]} / 8</td><td>{b["measurement_both"]} / 8</td><td>{a["unique_texts"]} / 8</td></tr>')
payload=json.dumps(rows,ensure_ascii=False).replace('<','\\u003c')
text='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Repeatability: the changing-length direction · TalkieAtlas</title><style>body{font:17px/1.55 system-ui,sans-serif;color:#222;background:#faf9f6;max-width:1120px;margin:40px auto;padding:0 24px}h1{font:700 clamp(30px,5vw,48px)/1.1 Georgia,serif;max-width:900px}h2{margin-top:42px}a{color:#0759ad}.lede{font-size:21px;max-width:900px}.table{overflow:auto}table{border-collapse:collapse;width:100%;background:white}th,td{text-align:left;padding:13px;border-bottom:1px solid #ddd;min-width:90px}th{font-size:14px}th:first-child,td:first-child{min-width:230px}.muted{color:#626262;font-size:14px}blockquote{background:white;border-left:4px solid #e8a147;margin:24px 0;padding:18px 24px;max-width:880px}.filters{display:flex;gap:14px;flex-wrap:wrap}select{font:inherit;padding:8px;max-width:100%}label{display:grid;gap:5px}details{background:white;border:1px solid #ddd;border-radius:10px;margin:14px 0;padding:16px}summary{cursor:pointer;font-weight:600}.reply{white-space:pre-wrap;overflow-wrap:anywhere}.tag{font-size:13px;color:#666}.method{max-width:900px}code{font-size:14px}footer{margin:50px 0;color:#666}</style><nav><a href="../../#id=b1011-r31">← Riddle candidate in the atlas</a> · <a href="data.json" download>All 134 replies and audit labels</a></nav><h1>Does this direction consistently make riddles?</h1><p class="lede"><strong>A consistent measurement-and-elongation pattern, with prompt-dependent riddle-like form.</strong> We retested L23 · N5442 · negative in Talkie-1930-13B-IT, without asking for riddles.</p><p>Both blinded reviewers flagged the measurement theme in <strong>32/32</strong> sampled original-strength outputs, versus <strong>1/32</strong> unsteered outputs. “Who are you?” produced riddle-like replies in <strong>8/8</strong> steered draws and <strong>0/8</strong> controls. Different wordings mostly revisit the same length, height and apparent-size frame.</p><h2>Across four prompts</h2><p class="muted">Eight sampled replies per cell. Riddle-like counts show both reviewers’ range where they disagreed; measurement counts require agreement. “Riddle-like” does not imply a valid or solvable puzzle.</p><div class="table"><table><thead><tr><th>Prompt</th><th>Riddle-like: original strength</th><th>Riddle-like: unsteered</th><th>Measurement: original strength</th><th>Measurement: unsteered</th><th>Distinct steered wordings</th></tr></thead><tbody>TABLE_ROWS</tbody></table></div><h2>The same theme reaches a garden prompt</h2><blockquote>Length is increased, and the dimensions of the garden appear greater than they really are, by lengthened lines, and the eminence of the ground is increased by height.</blockquote><p>The garden outputs use measurement language without becoming riddles. Half-strength steering produced the measurement theme in <strong>12/32</strong> sampled replies; the opposite sign produced <strong>0/32</strong>, requiring agreement from both reviewers.</p><h2>Literal repetition versus consistent territory</h2><p>The two identical greedy rows in one batch matched exactly. The singleton’s wording differed, and none of the three new greedy outputs exactly matched the archived original. All three returned to the length/height form. Greedy reproduction and thematic consistency are different checks; changing sampling seeds deliberately introduces further wording variation.</p><h2>Read every saved reply</h2><div class="filters"><label>Prompt<select id="prompt"></select></label><label>Condition<select id="condition"><option value="negative_original">Original negative strength (−1.25×)</option><option value="unsteered">Unsteered control</option><option value="negative_half">Half negative strength (−0.625×)</option><option value="positive_opposite">Opposite sign (+1.25×)</option><option value="all">All conditions</option></select></label><label>Decoding<select id="mode"><option value="sampled">Sampled, temperature 0.7</option><option value="all">All, including greedy tests</option><option value="greedy">Greedy only</option></select></label></div><p id="count" class="muted"></p><div id="replies"></div><h2>Method and limits</h2><div class="method"><p>128 sampled replies: four prompts × four conditions × eight matched seeds. Six additional greedy outputs test reproduction and controls. Full-vocabulary sampling at temperature 0.7, maximum 160 tokens, with the atlas’s repeat stopping. Each trial uses a shared uniform-number stream across conditions; every prompt is an independent native single-turn chat.</p><p>The edit adds the unit’s normalized effective MLP write direction after layer 23 at all prompt and generated positions. The learned MLP gain is included. The residual normalization and absolute edit magnitude are held fixed from the unsteered “Who are you?” prompt across all four prompts. No system persona or riddle instruction is supplied.</p><p>Two GPT-6 Luna subagents reviewed shuffled reply texts without prompt, dose, condition, or seed metadata. Their labels describe observable forms. They are not independent model families, and some cases are ambiguous. Eight draws per cell and four prompts cannot establish “always,” or prove the unit normally has a dedicated riddle function.</p><p>The source candidate was found in a prior exploratory screen. Some repeated outputs contain contradictions or broken logic. The defensible result is a reproducible writing pattern under this particular intervention, rather than demonstrated puzzle-making competence.</p></div><footer>TalkieAtlas · Benjamin Breen · Controlled follow-up, October 27, 2026. All saved outputs retained.</footer><script id="data" type="application/json">PAYLOAD</script><script>const rows=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const prompts=[...new Set(rows.map(r=>r.prompt))];$('prompt').innerHTML=prompts.map(p=>`<option>${esc(p)}</option>`).join('');function render(){const rs=rows.filter(r=>r.prompt===$('prompt').value&&($('condition').value==='all'||r.condition===$('condition').value)&&($('mode').value==='all'||($('mode').value==='sampled'?r.mode==='sampled':r.mode!=='sampled'))).sort((a,b)=>a.trial-b.trial||a.id.localeCompare(b.id));$('count').textContent=rs.length+' saved replies';$('replies').innerHTML=rs.map((r,i)=>`<details ${i===0?'open':''}><summary>Trial ${r.trial+1} · ${esc(r.condition)} · ${r.mode==='sampled'?'sampled':'greedy'}</summary><p class="tag">${esc(r.id)} · seed ${r.seed??'none'} · ${esc(r.termination)} · signed strength ${r.signed_alpha}×</p><p class="reply">${esc(r.text||'[Empty reply]')}</p>${r.audits.map((a,k)=>`<p class="tag">Reviewer ${k===0?'A':'B'}: riddle-like ${a.riddle_like?'yes':'no'}; measurement ${a.measurement_theme?'yes':'no'}; inconsistency ${a.internally_inconsistent?'yes':'no'}. ${esc(a.note)}</p>`).join('')}</details>`).join('')}for(const id of ['prompt','condition','mode'])$(id).onchange=render;render();</script></html>'''
text=text.replace('TABLE_ROWS',''.join(trs)).replace('PAYLOAD',payload);(run/'index.html').write_text(text)
(run/'status.json').write_text('{"phase":"complete","replies":134,"audit_reviews":268}\n')
print(json.dumps({'conditions':conditions,'agreement':agreement,'greedy':greedy_summary},ensure_ascii=False))
